typedef float time_value_t;

class stringx { public: const char *c_str() const; };
class frontend_map { public: void HideAllDots(); void PutUpLoadingScreen(); void PickDemo(int); };
class frontend_manager { public: bool fe_init; frontend_map *map; void ReloadTextures(); };
class os_developer_options { public: enum { FLAG_NO_AUDIO }; static os_developer_options *inst(); bool is_flagged(int); };
class game { public: stringx movie_name; void advance_state_play_fe_movie(time_value_t); void play_movie(const char *, bool, int, int); void soft_reset_process(); void set_render_state(int); };
extern frontend_manager frontendmanager;
extern game *g_game_ptr;
extern bool start_drawing_map;
extern void sceGsResetGraph(int, int, int, int);
extern void KSNGL_ReInit();
extern void nglResetDisplay();
extern bool nslInit();
extern void nglListInit();
extern void render_map_screen();
extern void nglListSend(bool);
extern void nglReleaseAllTextures();
enum { SCE_GS_INTERLACE, SCE_GS_NTSC, SCE_GS_FRAME, SCE_GS_PAL, GAME_RENDER_LOADING_LEVEL };

void game::advance_state_play_fe_movie( time_value_t time_inc )
{
#if !defined(TARGET_XBOX)
  frontendmanager.fe_init = false;
	//stash::close_stash(STASH_COMMON);
	//stash::free_stored(STASH_COMMON);

#if defined(TARGET_PS2)

#ifdef TV_PAL
  sceGsResetGraph( 0, SCE_GS_INTERLACE, SCE_GS_PAL, SCE_GS_FRAME );
  g_game_ptr->play_movie(movie_name.c_str(), true, 640, 512);
#else
  sceGsResetGraph( 0, SCE_GS_INTERLACE, SCE_GS_NTSC, SCE_GS_FRAME );
  g_game_ptr->play_movie(movie_name.c_str(), true, 640, 448);
#endif
  KSNGL_ReInit();
  nglResetDisplay();
  if (!os_developer_options::inst()->is_flagged(os_developer_options::FLAG_NO_AUDIO))
	  if (!nslInit())
	  {
#if defined(TARGET_XBOX) && defined(BUILD_FINAL)
		  // Xbox requires a message on all disk read failures.  (dc 07/11/02)
		  disk_read_error();
#endif
	  }

#elif defined(TARGET_GC)
  g_game_ptr->play_movie( movie_name.c_str( ), true );
#endif
  start_drawing_map = true;

	frontendmanager.ReloadTextures();
	frontendmanager.map->HideAllDots();
	frontendmanager.map->PutUpLoadingScreen();
	for (int i=0; i < 4; i++)
	{
		nglListInit();
		render_map_screen();
		nglListSend(true);
	}
	start_drawing_map = false;
	nglReleaseAllTextures();
  soft_reset_process();
	set_render_state(GAME_RENDER_LOADING_LEVEL);
  start_drawing_map = true;
  frontendmanager.map->PickDemo(0);

  //frontendmanager.map->PickFE();
	//((BeachFrontEnd *)frontendmanager.gms->menus[GraphicalMenuSystem::BeachMenu])->Pick();
	//frontendmanager.OnLevelEnding();
	//frontendmanager.in_game_map_up = true;
	//frontendmanager.IGO->ShowMenuBackground(false);

#endif
}
